function garment(p){if(garmentImages[p.imageKey||p.name.toLowerCase()])return `<img src="${garmentImages[p.imageKey||p.name.toLowerCase()]}" alt="${p.name}" loading="lazy" width="320" height="320">`;let shape=p.cat==='tops'||p.cat==='layers'?'<path d="m33 15-21 11 10 27 13-5v66h60V48l13 5 10-27-21-11-17-5c-5 12-16 12-21 0Z"/>':p.cat==='bottoms'?'<path d="M33 12h64l5 101H76L65 48 54 113H28Z"/>':'<path d="M21 61c4-17 9-28 18-28 13 0 10 22 26 28l38 14c12 5 13 19 0 22H24c-17 0-19-24-3-36Z"/><path d="m44 42 37 17c14 6 21-2 21-13l-4-23c-4-10-17-10-22-2L64 34Z"/>';return `<svg viewBox="0 0 130 130" role="img" aria-label="${p.name}"><g fill="${p.color}" stroke="#000" stroke-opacity=".13" stroke-width="1.5">${shape}</g><path d="M43 24v74m43-74v74" stroke="#fff" stroke-opacity=".12" fill="none"/></svg>`}
function btn(t,a,cls=''){return `<button class="${cls}" ${a}>${t}</button>`}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function current(){const base=outfits[state.index],key=selectedProfile();if(!key)return base;const profile=lookProfiles[key];return {...base,ids:profile.ids,image:profile.sheet,sheet:profile.sheet,isSheet:true,why:profile.why,steps:profile.steps,reasonGroups:base.reasonGroups.map((reason,i)=>({...reason,text:profile.reasons[i]}))};}function ids(){return state.swap?current().ids.map(id=>id===state.swap.from?state.swap.to:id):current().ids}
let rackCarousel;
let modelRenderRevision=0;
function render(){const previousViewer=window.requestAnimationFrame?$('#model-viewer'):null;const revision=++modelRenderRevision;if(rackCarousel){rackCarousel.destroy();rackCarousel=null;} $('#tabs').innerHTML=Object.keys(icons).map(t=>btn(`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[t]}</svg>${t}`,`data-tab="${t}" aria-current="${t===state.tab?'page':'false'}"`,t===state.tab?'active':'')).join('');$('#screen').className='screen-'+state.tab.toLowerCase();let content=({Today:today,Wardrobe:wardrobe,Shopping:verdict,Log:log})[state.tab]();let views=state.tab==='Today'?content.match(/<div class="segmented" aria-label="Today views">[\s\S]*?<\/div>/)?.[0]:'';if(views)content=content.replace(views,'');$('#screen').innerHTML=`<div class="page">${content}</div>`;$('#today-views').innerHTML=views||'';$('#today-views').hidden=!views;bind();bindEditor();mountRack();if(window.requestAnimationFrame){const nextViewer=$('#model-viewer');if(previousViewer&&nextViewer){nextViewer.replaceWith(previousViewer);Promise.all([...nextViewer.querySelectorAll('img')].map(image=>image.decode())).then(()=>{if(revision!==modelRenderRevision||!previousViewer.isConnected)return;previousViewer.replaceWith(nextViewer);bindModelViewer();}).catch(()=>{});}else bindModelViewer();} }
function today(){const previous=state.view;state.view='Outfit';const outfit=todayView().replace(/<div class="segmented" aria-label="Today views">[\s\S]*?<\/div>/,'');state.view='Wear';let wear=todayView();wear=wear.slice(wear.indexOf('<h2>How to wear it.'));state.view='Why';let why=todayView();why=why.slice(why.indexOf('<h2>Why it works.'));state.view=previous;return `<div class="today-flow"><section class="daily-outfit" aria-label="Your outfit">${outfit}</section><section class="daily-wear" aria-label="How to wear it"><p class="flow-chapter">02 / WEAR</p>${wear}</section><section class="daily-why" aria-label="Why it works"><p class="flow-chapter">03 / WHY</p>${why}</section></div>`;}
function todayView(){let o=current();let contexts={Confident:'A grounded shape with a little presence.',Approachable:'Soft textures keep the look open and easy.',Polished:'Keep the hems tidy and the finishing deliberate.',Relaxed:'Leave room to move. Let the fabrics fall naturally.',Sharp:'Clean lines, a neat hem, and no extra fuss.','Low-key':'Let the quiet details do the work.','Not sure':'Start here. See how it feels on you.'};return `<div class="topline"><span>YOUR DAILY EDIT</span><span><i class="dot"></i>${o.weather}</span></div><p class="morning-greeting">Good morning.</p><h2>What to wear.</h2><p class="sub">Your occasion. How you come across. Your own clothes.</p><div class="controls"><label>THE OCCASION<select id="occasion">${['Everyday / work','Casual afternoon','Date night'].map((x,i)=>`<option value="${i}" ${state.occasion===i?'selected':''}>${x}</option>`).join('')}</select></label><label>HOW YOU COME ACROSS<select id="energy">${['Confident','Approachable','Polished','Relaxed','Sharp','Low-key','Not sure'].map(x=>`<option ${state.energy===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="segmented" aria-label="Today views">${['Outfit','Wear','Why'].map(v=>btn(v,`data-view="${v}" aria-pressed="${state.view===v}"`,state.view===v?'active':'')).join('')}</div>${state.view==='Outfit'?`<div class="purpose-weather"><div><span>Purpose: ${['Everyday','Casual afternoon','Date night'][state.occasion]}</span><span>Style: ${o.style}</span></div><span class="energy-pill">Come across as: ${state.energy}</span></div>${modelViewer(o)}<div class="today-first-actions">${btn('Show me another outfit','id="another-outfit"','another-outfit secondary')}<div class="actions">${btn('✓ &nbsp; Wore it','data-log="wore"','primary')}${btn("Didn't wear it",'data-log="skipped"')}</div></div><div class="pick-heading"><h3>${o.name}</h3><span>FROM YOUR WARDROBE</span></div><p class="section-label">FROM YOUR WARDROBE</p><div class="outfit-piece-strip">${ids().map(id=>`<div class="outfit-piece-thumb">${garment(items[id])}<span>${items[id].name}</span></div>`).join('')}</div><p class="note">${o.line}</p>${state.swap?`<p class="hint">Swap preview: ${items[state.swap.to].name} replaces ${items[state.swap.from].name}. The photograph shows the original pick.</p>`:''}${btn(state.alternate?'↶ Back to your first pick':'↗ Show me one alternate','id="alternate"','text-button')}<p class="sub">Stylist’s note · ${o.stylistNote?o.stylistNote+' ':''}${contexts[state.energy]}</p>`:state.view==='Wear'?`<h2>How to wear it.</h2><p class="stylist-byline"><span>N</span><b>Nigel</b> Your stylist</p>${state.swap?`<div class="hint">For this swap, use ${items[state.swap.to].name} in place of ${items[state.swap.from].name} in the steps below.</div>`:''}<p class="sub">${o.short} · Come across as: ${state.energy}</p>${o.steps.map((s,i)=>`<div class="step"><span>0${i+1}</span><p>${s}${i===1?' '+contexts[state.energy]:''}</p></div>`).join('')}<div class="hint">Not sure how to wear it? We've got your back.</div>`:`<h2>Why it works.</h2><p class="sub">${o.goal}</p>${reasonCards(o)}<p class="note">${o.why} ${contexts[state.energy]} ${state.swap?state.swap.note:''}</p><p class="section-label">A SMALL CHANGE, A DIFFERENT FEEL</p>${(state.index===0?[[0,6,'A white tee makes the same silhouette quieter.'],[2,5,'White sneakers give the denim a lighter finish.']]:state.index===1?[[3,6,'White softens the contrast above the black shorts.'],[5,2,'Black clogs keep the outfit dark from top to toe.']]:[[15,13,'The navy chore jacket makes the same layers feel more casual.'],[16,5,'White sneakers give the slate trousers an everyday finish.']]).map(([from,to,n])=>btn(`${items[to].name} <span aria-hidden="true">↗</span>`,`data-swap="${from},${to}" data-note="${n}"`,'swap')).join('')}${state.swap?`<div class="hint">${state.swap.note}</div>`:''}<p class="section-label">YOUR LIKED PIECES IN ROTATION</p>${[...state.liked].map(id=>`<p class="pieces">♥ ${items[id].name}${items[id].cat==='layers'?' · Ready for the 16° date-night pick':' · Included in picks or alternate swaps'}</p>`).join('')}<p class="sub">Swaps come from your 20-piece demo wardrobe.</p>`}`}
function modelViewer(o){const sheet=o.sheet||`assets/turn-${turnSheets[state.index]}.png`;const label=['Front','Right side','Back','Left side'][state.modelAngle];const useSheet=o.isSheet||state.modelAngle!==0;return `<div class="photo-wrap model-viewer" id="model-viewer" role="slider" tabindex="0" aria-label="Turn outfit model" aria-valuemin="0" aria-valuemax="270" aria-valuenow="${state.modelAngle*90}" aria-valuetext="${label} view, ${o.short}" aria-describedby="model-turn-hint"><img class="outfit-photo" src="${o.isSheet?outfits[state.index].image:o.image}" alt="Faceless mannequin wearing ${o.ids.map(i=>items[i].name).join(', ')}" style="visibility:${useSheet?'hidden':'visible'}"><div class="model-turn-overlay" ${useSheet?'':'hidden'}><div class="model-turn-clip"><img class="model-turn-sheet" draggable="false" src="${sheet}" alt="${label} view of ${o.ids.map(i=>items[i].name).join(', ')}" style="transform:translateX(-${state.modelAngle*25}%)"></div></div>${btn('‹','id="model-prev" aria-label="Turn model left"','model-turn-arrow model-turn-prev')}${btn('›','id="model-next" aria-label="Turn model right"','model-turn-arrow model-turn-next')}<span class="model-turn-hint" id="model-turn-hint">${label} · Drag to turn · 4 views</span></div>`;}
function bindModelViewer(){const viewer=$('#model-viewer');if(!viewer)return;const labels=['Front','Right side','Back','Left side'];const show=angle=>{state.modelAngle=(angle+4)%4;const useSheet=current().isSheet||state.modelAngle!==0;viewer.querySelector('.outfit-photo').style.visibility=useSheet?'hidden':'visible';viewer.querySelector('.model-turn-overlay').hidden=!useSheet;viewer.querySelector('.model-turn-sheet').style.transform=`translateX(-${state.modelAngle*25}%)`;viewer.querySelector('.model-turn-sheet').alt=`${labels[state.modelAngle]} view of ${current().short}`;viewer.querySelector('.model-turn-hint').textContent=`${labels[state.modelAngle]} · Drag to turn · 4 views`;viewer.setAttribute('aria-valuenow',String(state.modelAngle*90));viewer.setAttribute('aria-valuetext',`${labels[state.modelAngle]} view, ${current().short}`);};const image=viewer.querySelector('.model-turn-sheet');image.decode().then(()=>{viewer.querySelector('.model-turn-clip').style.aspectRatio=String(image.naturalWidth/4/image.naturalHeight);}).catch(()=>{viewer.querySelector('.model-turn-hint').textContent='Turn views unavailable. Please reload.';});$('#model-prev').onclick=()=>show(state.modelAngle-1);$('#model-next').onclick=()=>show(state.modelAngle+1);viewer.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(state.modelAngle+(e.key==='ArrowRight'?1:-1));}else if(e.key==='Home'){e.preventDefault();show(0);}};let drag=null;viewer.onpointerdown=e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,index:state.modelAngle,id:e.pointerId};};viewer.onpointermove=e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dy)>Math.abs(dx)&&Math.abs(dy)>12){drag=null;return;}if(Math.abs(dx)>12){viewer.setPointerCapture(e.pointerId);show(drag.index+Math.round(-dx/45));}};viewer.onpointerup=viewer.onpointercancel=e=>{if(viewer.hasPointerCapture(e.pointerId))viewer.releasePointerCapture(e.pointerId);drag=null;};}
function reasonCards(o){const active=state.reasonIndex%o.reasonGroups.length;return `<div class="reason-selector" role="group" aria-label="Outfit details">${o.reasonGroups.map((r,i)=>btn(garment(items[o.ids[Math.min(i,o.ids.length-1)]]),`data-reason="${i}" aria-label="${r.title}" aria-pressed="${active===i}"`,active===i?'active':'')).join('')}</div><div class="reason-cards">${o.reasonGroups.map((r,i)=>btn(`<strong>${r.title}</strong><span>${r.text}</span>`,`data-reason="${i}" aria-pressed="${active===i}"`,active===i?'reason-card active':'reason-card')).join('')}</div>`}
function wardrobeEditor(){const p=items[state.editing];const input=(key,label)=>`<label>${label}<input name="${key}" value="${escapeHTML(p[key])}" maxlength="${key==='name'?80:100}"></label>`;const select=(key,label,options)=>`<label>${label}<select name="${key}">${options.map(v=>`<option value="${v}" ${p[key]===v?'selected':''}>${v}</option>`).join('')}</select></label>`;return `<section class="wardrobe-edit-panel" aria-labelledby="edit-title"><div class="editor-title"><div><p class="section-label">PIECE ${String(p.id+1).padStart(2,'0')}</p><h3 id="edit-title">The details matter.</h3></div>${btn('×','id="close-editor" aria-label="Close clothing editor"')}</div><div class="editor-preview">${garment(p)}</div><form id="piece-editor"><div class="editor-fields">${input('name','Piece name')}${select('cat','Category',['tops','bottoms','shoes','layers'])}${input('colour','Colour')}${input('material','Material')}${select('fit','Fit',['Not tagged','Slim','Regular','Relaxed','Oversized','Straight','Tapered'])}${select('pattern','Pattern',['Plain','Striped','Checked','Printed','Textured','Other'])}<label>Seasons<input name="seasons" value="${escapeHTML(p.seasons.join(', '))}" placeholder="Spring, summer"></label><label>Occasions<input name="occasions" value="${escapeHTML(p.occasions.join(', '))}" placeholder="Everyday, work"></label><label class="full">Notes<textarea name="notes" rows="3" maxlength="500" placeholder="Fit notes, care, or details to remember">${escapeHTML(p.notes)}</textarea></label></div><p class="editor-message" id="editor-message" role="status">Use commas to separate season and occasion tags.</p><div class="actions">${btn('Save details','type="submit"','primary')}${btn('Cancel','type="button" id="cancel-editor"')}</div></form></section>`;}
function applyPieceEdits(id,values){if(!/^[^<>"&`]{1,80}$/.test(values.name?.trim()||''))throw Error('Use a piece name of 1–80 characters without markup.');if(!['tops','bottoms','shoes','layers'].includes(values.cat))throw Error('Choose a valid category.');const p=items[id];p.name=values.name.trim();p.cat=values.cat;for(const key of ['colour','material','fit','pattern','notes'])p[key]=String(values[key]||'').trim().slice(0,key==='notes'?500:100);for(const key of ['seasons','occasions'])p[key]=String(values[key]||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,12);return saveWardrobe();}
function bindEditor(){document.querySelectorAll('[data-edit-piece]').forEach(b=>b.onclick=()=>{state.editing=+b.dataset.editPiece;render();$('#screen').scrollTop=0;});for(const id of ['close-editor','cancel-editor'])if($('#'+id))$('#'+id).onclick=()=>{state.editing=null;render();};if($('#piece-editor'))$('#piece-editor').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));try{const saved=applyPieceEdits(state.editing,values);state.editing=null;render();toast(saved?'Clothing details saved on this browser.':'Details updated for this session. Browser storage is unavailable.');}catch(error){$('#editor-message').textContent=error.message;}};if($('#export-wardrobe'))$('#export-wardrobe').onclick=()=>{const blob=new Blob([JSON.stringify(wardrobeData(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='composed-wardrobe.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
function compatible(p){if(!state.fit.length)return true;let anchor=items[state.anchor];return p.id===state.anchor||!state.fit.some(id=>items[id].cat===p.cat)&&(anchor.style===p.style||p.style==='Everyday'||anchor.style==='Everyday'||['shoes','layers'].includes(p.cat))}
function complete(){return (current().requireLayer?['tops','bottoms','shoes','layers']:['tops','bottoms','shoes']).every(c=>state.fit.some(i=>items[i].cat===c))}
function wardrobe(){let shown=items.filter(p=>(state.filter==='All'||p.cat===state.filter.toLowerCase())&&(state.anchor===null||compatible(p)||state.fit.includes(p.id)));return `<div class="topline"><span>LESS, BUT BETTER</span><span>20 PIECES</span></div><h2>Your wardrobe.</h2><p class="sub">The good things you already own. Keep their details considered, too.</p><div class="wardrobe-tools">${btn('Export wardrobe','id="export-wardrobe"')}<span>Edits saved on this browser · no AI analysis yet</span></div><div class="wardrobe-view-toggle" role="group" aria-label="Wardrobe display">${['Rack','List'].map(v=>btn(v,`data-wardrobe-view="${v}" aria-pressed="${state.wardrobeView===v}"`,state.wardrobeView===v?'active':'')).join('')}</div>${state.editing!==null?wardrobeEditor():''}${state.anchor!==null?`<div class="builder"><strong>Build around ${items[state.anchor].name}</strong><p>${state.fit.map(i=>items[i].name).join(' + ')}</p><p>${complete()?'Your fit is complete. The layers match today’s weather.':'Choose '+(current().requireLayer?['tops','bottoms','shoes','layers']:['tops','bottoms','shoes']).filter(c=>!state.fit.some(i=>items[i].cat===c)).join(', ')+'. Compatible pieces are shown below.'}</p>${complete()?btn('Save fit','id="save-fit"','primary')+btn('Ask for a critique','id="critique"'):''}${btn('Start over','id="clear-fit"','text-button')}</div>`:'<div class="hint">BUILD A FIT · Tap a piece to make it your starting point. Tap ♡ to keep it in your rotation.</div>'}<div class="filters">${['All','Tops','Bottoms','Shoes','Layers'].map(f=>btn(f,`data-filter="${f}"`,state.filter===f?'active':'')).join('')}</div><p class="rack-instruction">${state.wardrobeView==='Rack'?'Swipe to browse · tap a garment to turn it forward':'Your pieces, at a glance · tap to build a fit'}</p>${state.wardrobeView==='Rack'?landingRail(shown):`<div class="wardrobe-display ${state.wardrobeView==='Rack'?'rack-display':'list-display'}" aria-label="${state.wardrobeView==='Rack'?'Clothing rack':'Wardrobe list'}"><div class="rack-track">${shown.map(p=>`<article class="item ${p.cat==='shoes'?'shelf-item':'hanging-item'} ${state.fit.includes(p.id)?'selected':''}">${btn(`<div class="garment">${p.cat!=='shoes'?'<svg class="rack-hanger" viewBox="0 0 24 24" aria-hidden="true"><path d="M14 6a2 2 0 1 0 -4 0c0 1.667 .67 3 2 4h-.008l7.971 4.428a2 2 0 0 1 1.029 1.749v.823a2 2 0 0 1 -2 2h-14a2 2 0 0 1 -2 -2v-.823a2 2 0 0 1 1.029 -1.749l7.971 -4.428"/></svg>':''}${garment(p)}</div><span class="item-name">${p.name}</span><small>${p.style}${state.fit.includes(p.id)?' · Selected':''}</small>`,`data-piece="${p.id}" aria-label="Build a fit with ${p.name}"`)}${btn(state.liked.has(p.id)?'♥':'♡',`data-like="${p.id}" aria-label="${state.liked.has(p.id)?'Unlike':'Like'} ${p.name}" aria-pressed="${state.liked.has(p.id)}"`,'like')}${btn('Edit details',`data-edit-piece="${p.id}" aria-label="Edit ${p.name}"`,'edit-piece')}</article>`).join('')}</div></div>${state.wardrobeView==='Rack'?`<div class="rack-navigation">${btn('←','data-rack-step="-1" aria-label="Previous garment"')}<span id="rack-position">Swipe or drag to browse</span>${btn('→','data-rack-step="1" aria-label="Next garment"')}</div>`:''}`}${state.saved.length?`<p class="section-label">SAVED FITS · ${state.saved.length}</p>${state.saved.map((f,i)=>`<p class="note">Fit ${i+1} · ${f.map(id=>items[id].name).join(', ')}</p>`).join('')}`:''}`}
const cases=[{"id":14,"word":"Skip it","match":"Good","why":"Yes, it fits your style. Short hem balances your longer torso, clean shape fits Japanese minimal, and black fits your cool, deep winter colours.","adds":"Nothing. Your black bomber already covers this shape and colour.","checks":["Short hem balances your longer torso.","Clean shape fits Japanese minimal.","Black fits your cool, deep winter colours."]},{"id":15,"word":"Skip it","match":"Poor","why":"No, it does not fit your style. A long hem may shorten your leg line, utility details lean away from Japanese minimal, and warm olive is outside deep winter.","adds":"Little. This muted olive adds little to your current wardrobe. Your olive cotton overshirt already covers a relaxed olive layer.","checks":["A long hem may shorten your leg line.","Utility details lean away from Japanese minimal.","Warm olive is outside deep winter."]},{"id":17,"word":"Worth trying on","match":"Good","why":"Simple loafers suit Japanese minimal, and cool grey fits better than warm stone.","adds":"A lighter shoe for smarter outfits. Your black loafers do not cover this.","with":"Dark indigo jeans, or the slate pleated trousers from Date night.","check":"Pale shoes may interrupt your leg line, so check it in a full length mirror, with the trousers you would actually wear.","checks":["Pale shoes may interrupt your leg line.","Simple loafers suit Japanese minimal.","Cool grey fits better than warm stone."]}];
function verdict(){let c=cases[state.verdict],p=items[c.id];return `<div class="shopping-workspace"><h2>Worth it?</h2><p class="sub">Check it against your wardrobe.</p><div class="shopping-options" role="group" aria-label="Possible purchase">${cases.map((c,i)=>btn(['Jacket','Overshirt','Loafers'][i],`data-purchase="${i}" aria-pressed="${state.verdict===i}"`,state.verdict===i?'active':'')).join('')}</div><label class="purchase-select">Possible purchase<select id="purchase">${cases.map((c,i)=>`<option value="${i}" ${state.verdict===i?'selected':''}>${items[c.id].name}</option>`).join('')}</select></label><div class="shopping-body"><div class="verdict-image purchase-photo"><img src="assets/purchase-${state.verdict}.webp" alt="${p.name}, photographed in store" width="1122" height="1402"><span class="store-photo-label">${state.verdict===2?'On display':'On the hanger'}</span></div><div class="shopping-answer"><h3 class="verdict-word ${state.verdict===2?'accent':''}">${c.word}</h3><span class="match">${c.match.toUpperCase()} MATCH</span><h4>${p.name}</h4><p class="note">${c.why}</p><div class="detail"><strong>${state.verdict===2?'WHAT IT ADDS':'ALREADY COVERED'}</strong>${c.adds}</div>${c.with?`<div class="detail"><strong>WEAR IT WITH</strong>${c.with}</div><div class="detail"><strong>IN THE FITTING ROOM</strong>${c.check}</div>`:''}${c.checks.map((s,i)=>`<div class="shopping-check"><strong>${['Proportions','Target style','Palette'][i]}:</strong> ${s}</div>`).join('')}</div></div><div class="shopping-bottom"><p class="sub">Sample wardrobe advice. No live photo analysis.</p></div></div>`;}
function log(){let worn=state.logs.filter(l=>l.type==='wore'),skipped=state.logs.filter(l=>l.type==='skipped'),used=new Set(worn.flatMap(l=>l.ids)),mix=state.mix==='Owned'?items:state.mix==='Liked'?items.filter(p=>state.liked.has(p.id)):worn.flatMap(l=>l.ids.map(id=>items[id]));let counts={};worn.forEach(l=>l.ids.forEach(id=>counts[id]=(counts[id]||0)+1));let sorted=Object.keys(counts).sort((a,b)=>counts[b]-counts[a]);return `<div class="topline"><span>SMALL HABITS, GOOD INSIGHT</span><span>THIS WEEK</span></div><h2>It starts with a day.</h2><p class="sub">What you reach for tells us something.</p><div class="stats"><div class="stat"><b>${state.logs.length?1:0}<small> day</small></b><span>Logging streak</span></div><div class="stat"><b>${used.size}<small> / 20</small></b><span>Closet pieces worn</span></div></div>${[['WORE IT',worn],['DIDN’T WEAR IT',skipped]].map(([title,logs])=>`<p class="section-label">${title} · ${logs.length}</p>${logs.length?logs.map(l=>`<div class="log-row">${l.name}<br><small>${l.ids.map(i=>items[i].name).join(' · ')}<br>${l.date}</small></div>`).join(''):'<p class="empty">No outfits logged here yet.</p>'}`).join('')}<p class="section-label">COST PER WEAR</p>${sorted.length?`<p class="sub">Illustrative wardrobe costs, per wear. Demo units, not purchase prices.</p>${[...new Set([sorted[0],sorted[sorted.length-1]])].map((id,i)=>`<div class="log-row">${items[id].name}<br><small>${i?'Least worn':'Most worn'} · ${counts[id]} wear${counts[id]>1?'s':''} · ${(items[id].cost/counts[id]).toFixed(1)} cost units / wear</small></div>`).join('')}`:'<p class="empty">Log a wear to see which pieces earn their place.</p>'}<p class="section-label">STYLE MIX</p><div class="segmented">${['Owned','Worn','Liked'].map(v=>btn(v,`data-mix="${v}"`,state.mix===v?'active':'')).join('')}</div>${['Everyday','Considered','Relaxed'].map(s=>`<div class="mix-row"><span>${s}</span><span>${mix.filter(p=>p.style===s).length} ${state.mix==='Worn'?'wears':'pieces'}</span></div>`).join('')}<p class="section-label">OFFERED, BUT REJECTED</p>${skipped.length?[...new Set(skipped.flatMap(l=>l.ids))].map(id=>`<div class="log-row">${items[id].name}<br><small>Offered, not counted as worn</small></div>`).join(''):'<p class="empty">Skipped pieces will appear separately here.</p>'}<div class="hint">Interactive demo. Nothing is saved.<br>Your log and saved fits reset when you reload.</div>`}
function likedAlternate(){let candidates=[...state.liked].filter(id=>!current().ids.includes(id)&&items[id].cat!=='layers');if(!candidates.length)return;let to=candidates[state.rotation++%candidates.length],from=current().ids.find(id=>items[id].cat===items[to].cat);if(from!==undefined)state.swap={from,to,note:`Your liked ${items[to].name} joins this rotation. It gives the ${current().short.toLowerCase()} silhouette a ${items[to].style.toLowerCase()} feel.`}}
function choose(){state.index=state.occasion;state.alternate=false;state.swap=null;state.modelAngle=0}
