function railGarments(shown){const rank=id=>{const i=outfits.flatMap(o=>o.ids).indexOf(id);return i<0?999:i;};return shown.filter(p=>p.cat!=='shoes'&&garmentImages[p.imageKey]).sort((a,b)=>Number(a.cat==='bottoms')-Number(b.cat==='bottoms')||rank(a.id)-rank(b.id));}
function railActions(p){return `<div><h3 id="rail-name">${p.name}</h3><p>${p.cat} · ${p.material==='Not tagged'?p.style:escapeHTML(p.material)}</p></div><div class="rail-controls">${btn('←','id="rail-prev" aria-label="Previous garment"')}<span id="rail-counter"></span>${btn('→','id="rail-next" aria-label="Next garment"')}</div><div class="rail-piece-actions">${btn('Build a fit','id="rail-build"','primary')}${btn('Edit details','id="rail-edit"')}${btn(state.liked.has(p.id)?'♥ Liked':'♡ Like','id="rail-like"')}</div>`;}
function landingRail(shown){const garments=railGarments(shown);if(!garments.some(p=>p.id===state.railSelected))state.railSelected=garments[0]?.id??null;const selected=garments.find(p=>p.id===state.railSelected);return `<div class="landing-rail">${garments.length?`<div class="photographic-rail" aria-label="Clothing rail"><div class="hanger-track"><div class="photographic-rail-bar" aria-hidden="true"></div>${garments.map((p,i)=>{const front=garmentImages[p.imageKey]||garmentImages[p.name.toLowerCase()];const side=front?.replace('-front-320','-side-640');const detail=front?.replace('-front-320','-front-960');const group=i===0||p.cat==='bottoms'&&garments[i-1].cat!=='bottoms';return btn(`<span class="rail-photographs">${front?`<img class="rail-product-front" src="${detail}" alt="${p.name}" width="320" height="320"><img class="rail-product-side" src="${side}" alt="" aria-hidden="true" width="640" height="640" loading="lazy">`:`<span class="rail-product-front">${garment(p)}</span><span class="rail-product-side drawn-side">${garment(p)}</span>`}</span>${group?`<span class="rail-group-label" aria-hidden="true">${p.cat==='bottoms'?'BOTTOMS':'TOPS & LAYERS'}</span>`:''}`,`data-rail="${p.id}" data-category="${p.cat==='bottoms'?(p.imageKey.includes('jeans')?'jeans':p.imageKey.includes('shorts')?'shorts':'trousers'):'outerwear'}" aria-label="Face forward: ${p.name}" aria-pressed="${p.id===state.railSelected}"`,'hanger-button'+(p.id===state.railSelected?' face':'')+(group&&i?' rail-group-start':''));}).join('')}</div></div><div class="rail-caption" id="rail-caption">${railActions(selected)}</div>`:''}${shown.some(p=>p.cat==='shoes')?`<details class="landing-shoe-shelf shoe-drawer" open><summary>Shoe drawer <small>${shown.filter(p=>p.cat==='shoes').length} pairs</small></summary><div class="shoe-shelf">${shown.filter(p=>p.cat==='shoes').map(p=>`<article class="shelf-item">${btn(`${garment(p)}<span>${p.name}</span>`,`data-piece="${p.id}" aria-label="Build a fit with ${p.name}"`)}${btn('Edit details',`data-edit-piece="${p.id}"`,'edit-piece')}${btn(state.liked.has(p.id)?'♥':'♡',`data-like="${p.id}" aria-label="Like ${p.name}"`)}</article>`).join('')}</div></details>`:''}${shown.some(p=>p.cat!=='shoes'&&!garmentImages[p.imageKey])?'<p class="sub">Pieces without rail photographs are available in List view.</p>':''}</div>`;}
function mountRack(){const rail=$('.photographic-rail');if(!rail)return;const garments=railGarments(items.filter(p=>(state.filter==='All'||p.cat===state.filter.toLowerCase())&&(state.anchor===null||compatible(p)||state.fit.includes(p.id))));const buttons=[...rail.querySelectorAll('[data-rail]')];let selected=Math.max(0,garments.findIndex(p=>p.id===state.railSelected));const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
function show(index){const p=garments[index];buttons.forEach((b,i)=>{b.classList.toggle('face',i===index);b.setAttribute('aria-pressed',String(i===selected));});$('#rail-caption').innerHTML=railActions(p);$('#rail-counter').textContent=`${String(index+1).padStart(2,'0')} / ${garments.length}`;$('#rail-prev').disabled=selected===0;$('#rail-next').disabled=selected===garments.length-1;$('#rail-prev').onclick=()=>select(selected-1,true);$('#rail-next').onclick=()=>select(selected+1,true);$('#rail-build').onclick=()=>{state.anchor=garments[selected].id;state.fit=[state.anchor];render();};$('#rail-edit').onclick=()=>{state.editing=garments[selected].id;render();$('#screen').scrollTop=0;};$('#rail-like').onclick=()=>{const id=garments[selected].id;state.liked.has(id)?state.liked.delete(id):state.liked.add(id);show(selected);};}
function select(index,scroll=false){selected=Math.max(0,Math.min(garments.length-1,index));state.railSelected=garments[selected].id;show(selected);if(scroll)rail.scrollTo({left:Math.max(0,buttons[selected].offsetLeft-rail.clientWidth/2+90),behavior:reduced?'instant':'smooth'});}
buttons.forEach((b,i)=>{b.onpointerenter=e=>{if(e.pointerType!=='touch')show(i);};b.onfocus=()=>select(i);b.onclick=()=>select(i);});rail.onpointerleave=()=>show(selected);rail.onpointercancel=()=>show(selected);rail.onfocusout=e=>{if(!rail.contains(e.relatedTarget))show(selected);};rail.onkeydown=e=>{const targets={ArrowLeft:selected-1,ArrowRight:selected+1,Home:0,End:garments.length-1};if(e.key in targets){e.preventDefault();select(targets[e.key],true);buttons[selected].focus({preventScroll:true});}};select(selected);}
function toggleAlternate(){state.alternate=!state.alternate;state.modelAngle=0;state.swap=null;render();$('#screen').scrollTop=0;}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render();$('#screen').scrollTop=0});document.querySelectorAll('[data-wardrobe-view]').forEach(b=>b.onclick=()=>{state.wardrobeView=b.dataset.wardrobeView;render()});document.querySelectorAll('[data-purchase]').forEach(b=>b.onclick=()=>{state.verdict=+b.dataset.purchase;render()});document.querySelectorAll('[data-reason]').forEach(b=>b.onclick=()=>{state.reasonIndex=+b.dataset.reason;render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});if($('#occasion'))$('#occasion').onchange=e=>{state.occasion=+e.target.value;choose();render();$('#screen').scrollTop=0};if($('#energy'))$('#energy').onchange=e=>{state.energy=e.target.value;state.alternate=false;state.swap=null;state.modelAngle=0;state.reasonIndex=0;render();$('#screen').scrollTop=0};for(const id of ['alternate','another-outfit'])if($('#'+id))$('#'+id).onclick=toggleAlternate;document.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>{state.logs.push({type:b.dataset.log,ids:[...ids()],name:current().short,date:new Intl.DateTimeFormat('en',{weekday:'short',month:'short',day:'numeric'}).format(new Date())});toast(b.dataset.log==='wore'?'Wore it. Your log has been updated.':'Logged as not worn. We’ll keep that separate.');});document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>{let [from,to]=b.dataset.swap.split(',').map(Number);state.swap={from,to,note:b.dataset.note};render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;state.rackIndex=0;render()});document.querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>{let id=+b.dataset.like;state.liked.has(id)?state.liked.delete(id):state.liked.add(id);render();toast('Rotation preference updated for this session.')});document.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>{let id=+b.dataset.piece;if(state.anchor===null){state.anchor=id;state.fit=[id]}else if(id!==state.anchor){state.fit=state.fit.filter(i=>items[i].cat!==items[id].cat);state.fit.push(id)}render()});if($('#clear-fit'))$('#clear-fit').onclick=()=>{state.anchor=null;state.fit=[];state.filter='All';render()};if($('#save-fit'))$('#save-fit').onclick=()=>{state.saved.push([...state.fit]);toast('Fit saved for this session.');render()};if($('#critique'))$('#critique').onclick=()=>{let shoe=state.fit.find(id=>items[id].cat==='shoes'),replacement=shoe===5?17:5;toast(`Try one swap: ${items[shoe].name} → ${items[replacement].name} for a ${replacement===5?'lighter, casual':'softer, polished'} finish.`)};if($('#purchase'))$('#purchase').onchange=e=>{state.verdict=+e.target.value;render()};document.querySelectorAll('[data-mix]').forEach(b=>b.onclick=()=>{state.mix=b.dataset.mix;render()})}
if($('#record-mode'))$('#record-mode').onclick=()=>{const active=document.body.classList.toggle('record-mode');$('#record-mode').setAttribute('aria-pressed',String(active));};
function theme(){const dark=document.body.classList.toggle('dark');$('#theme-mobile').setAttribute?.('aria-pressed',String(dark));$('#theme-mobile').setAttribute?.('aria-label',dark?'Switch to light mode':'Switch to dark mode');}$('#theme-mobile').onclick=theme;render();
